insert into public.hobbies (id, name, emoji, color, category, description, long_description, member_count, sort_order) values
  ('photography', 'Photography', '📸', '#4D7CFE', 'Creative', 'Capture moments, play with light, and see the world through a different lens.', 'From street photography to portraits, film to digital — photography is about noticing what others walk past.', 284, 0),
  ('guitar', 'Guitar', '🎸', '#FF914D', 'Music', 'Strum, pick, shred. Whether acoustic or electric, make some noise.', 'Learn chords, jam with friends, write songs, or just play alone at 2am when you can''t sleep.', 196, 1),
  ('pottery', 'Pottery', '🏺', '#FF914D', 'Creative', 'Get your hands dirty. Shape clay into something beautiful (or weird).', 'There''s something meditative about centering clay on a wheel. Plus you end up with mugs.', 87, 2),
  ('running', 'Running', '🏃', '#5BCB77', 'Fitness', 'Just you, the road, and your thoughts. Or a podcast.', 'From couch-to-5K beginners to marathon veterans. Running is the most accessible sport there is.', 342, 3),
  ('film', 'Film', '🎬', '#9B72FF', 'Creative', 'Watch critically, discuss passionately, maybe even make your own.', 'Dive into cinema — from indie gems to blockbusters, foreign films to documentaries.', 215, 4),
  ('ai-ml', 'AI & Machine Learning', '🤖', '#4D7CFE', 'Tech', 'Build intelligent systems. Understand how machines learn.', 'From neural networks to natural language processing. The future is being written in Python.', 178, 5),
  ('drawing', 'Drawing', '✏️', '#FFD43B', 'Creative', 'Pencil, pen, tablet — put what''s in your head onto paper.', 'Sketching, illustration, comics, figure drawing. The most fundamental visual art.', 231, 6),
  ('writing', 'Writing', '✍️', '#FF72B6', 'Creative', 'Stories, poems, essays, journals. Words are your medium.', 'Whether you''re writing the next great novel or just journaling before bed.', 156, 7),
  ('cooking', 'Cooking', '🍳', '#FF5C5C', 'Lifestyle', 'Feed yourself something better than instant ramen.', 'Explore cuisines, master techniques, share recipes, and actually enjoy your meals.', 289, 8),
  ('bouldering', 'Bouldering', '🧗', '#FF914D', 'Fitness', 'Solve problems with your body. Climb walls. Fall on mats.', 'Bouldering is puzzle-solving meets physical challenge. The community is incredibly welcoming.', 124, 9),
  ('dance', 'Dance', '💃', '#FF72B6', 'Performance', 'Move your body. Express yourself. Learn choreography or freestyle.', 'Hip-hop, contemporary, salsa, breaking — find your style and your rhythm.', 167, 10),
  ('chess', 'Chess', '♟️', '#111111', 'Strategy', '64 squares, infinite possibilities. The original strategy game.', 'Openings, endgames, tactics, blitz. Chess is having a renaissance and you should be part of it.', 203, 11),
  ('gardening', 'Gardening', '🌱', '#5BCB77', 'Lifestyle', 'Grow things. Watch them bloom. Feel unreasonably proud.', 'Even a tiny balcony garden counts. Herbs, flowers, vegetables — nature doesn''t need much space.', 94, 12),
  ('gaming', 'Gaming', '🎮', '#9B72FF', 'Entertainment', 'Play, compete, explore virtual worlds, tell interactive stories.', 'From indie narrative games to competitive esports. Gaming is the broadest entertainment medium.', 412, 13),
  ('fashion', 'Fashion', '👗', '#FF72B6', 'Creative', 'Express yourself through what you wear. Thrift, design, style.', 'Streetwear, vintage, sustainable fashion, design. Clothing as creative expression.', 143, 14),
  ('woodworking', 'Woodworking', '🪚', '#FF914D', 'Making', 'Build real things with your hands. Shelves, boxes, furniture.', 'There''s nothing like the satisfaction of making something functional from raw wood.', 68, 15),
  ('cycling', 'Cycling', '🚴', '#5BCB77', 'Fitness', 'Pedal through cities, trails, or just your neighbourhood.', 'Road cycling, mountain biking, bike commuting, bike touring. Two wheels, endless possibilities.', 176, 16),
  ('astronomy', 'Astronomy', '🔭', '#4D7CFE', 'Science', 'Look up. The universe is absurdly beautiful.', 'Stargazing, astrophotography, learning about galaxies. Space is the ultimate frontier.', 92, 17),
  ('calligraphy', 'Calligraphy', '🖊️', '#FFD43B', 'Creative', 'Beautiful writing as an art form. Ink, nibs, and patience.', 'Modern calligraphy, traditional scripts, brush lettering. Slow down and make letters beautiful.', 54, 18),
  ('skateboarding', 'Skateboarding', '🛹', '#FF5C5C', 'Sports', 'Four wheels, infinite tricks. Fall down, get back up.', 'Skateboarding is a culture, not just a sport. Street, park, vert — find your terrain.', 118, 19)
insert into public.communities (id, hobby_id, name, description, member_count, post_count, color, trending, tags, related_hobbies, sort_order) values
  ('street-photography', 'photography', 'Street Photography', 'Capturing life as it happens. Candid moments, urban scenes, and the art of being invisible with a camera.', 142, 89, '#4D7CFE', true, array['photography', 'street', 'urban'], array['film', 'drawing', 'cycling'], 0),
  ('film-photography', 'photography', 'Film Photography', 'Analog vibes. Shooting on film, developing rolls, and embracing the beautiful imperfection of grain.', 98, 56, '#4D7CFE', false, array['photography', 'film', 'analog'], array['photography', 'film'], 1),
  ('acoustic-sessions', 'guitar', 'Acoustic Sessions', 'Campfire chords and fingerpicking patterns. Share tabs, recordings, and the struggle of barre chords.', 87, 44, '#FF914D', true, array['guitar', 'acoustic', 'music'], array['writing', 'dance'], 2),
  ('couch-to-5k', 'running', 'Couch to 5K', 'Starting from zero. A supportive community for people who just started running and want to not die.', 234, 167, '#5BCB77', true, array['running', 'beginner', 'fitness'], array['cycling', 'bouldering'], 3),
  ('trail-runners', 'running', 'Trail Runners', 'Ditch the treadmill. Find trails, share routes, and get muddy.', 108, 72, '#5BCB77', false, array['running', 'trail', 'outdoors'], array['cycling', 'bouldering'], 4),
  ('cinema-club', 'film', 'Cinema Club', 'Weekly film picks, deep discussions, and hot takes. From Tarkovsky to Tarantino.', 176, 134, '#9B72FF', true, array['film', 'movies', 'discussion'], array['writing', 'photography'], 5),
  ('ml-study-group', 'ai-ml', 'ML Study Group', 'Learning machine learning together. Papers, projects, and the eternal battle with PyTorch.', 94, 58, '#4D7CFE', false, array['ai', 'machine-learning', 'tech'], array['chess', 'gaming'], 6),
  ('sketch-daily', 'drawing', 'Sketch Daily', 'Draw something every day. Share your sketches, get feedback, improve together.', 189, 312, '#FFD43B', true, array['drawing', 'sketching', 'daily'], array['calligraphy', 'photography'], 7),
  ('student-chefs', 'cooking', 'Student Chefs', 'Cooking on a budget with a microwave and a dream. Recipes that won''t break the bank.', 201, 145, '#FF5C5C', true, array['cooking', 'student', 'recipes'], array['gardening'], 8),
  ('beta-crushers', 'bouldering', 'Beta Crushers', 'Share beta, celebrate sends, and commiserate about that one V4 that haunts your dreams.', 89, 67, '#FF914D', false, array['bouldering', 'climbing', 'fitness'], array['running', 'cycling'], 9),
  ('creative-writing-circle', 'writing', 'Creative Writing Circle', 'Share your writing, give feedback, and procrastinate on your novel together.', 112, 89, '#FF72B6', false, array['writing', 'creative', 'fiction'], array['film', 'drawing'], 10),
  ('chess-beginners', 'chess', 'Chess for Beginners', 'Learning the game from scratch. No judgment, just pawns and patience.', 156, 98, '#111111', true, array['chess', 'beginner', 'strategy'], array['ai-ml', 'gaming'], 11),
  ('indie-game-nights', 'gaming', 'Indie Game Nights', 'Forget AAA. We play the weird, beautiful, broken indie games nobody talks about.', 134, 91, '#9B72FF', false, array['gaming', 'indie', 'community'], array['film', 'drawing'], 12),
  ('plant-parents', 'gardening', 'Plant Parents', 'Keeping plants alive is harder than it looks. Share tips, mourn losses, celebrate blooms.', 76, 54, '#5BCB77', false, array['gardening', 'plants', 'lifestyle'], array['cooking', 'pottery'], 13),
  ('dance-freestyle', 'dance', 'Freestyle Flow', 'No choreography, no rules. Just move to the music and share your sessions.', 91, 63, '#FF72B6', false, array['dance', 'freestyle', 'expression'], array['skateboarding', 'fashion'], 14),
  ('book-nook', 'writing', 'Book Nook', 'Monthly reads, cozy annotations and endless TBR piles. Bring a book, leave with three more.', 96, 52, '#9B72FF', false, array['books', 'reading', 'writing'], array['writing', 'calligraphy'], 15),
  ('bouldering-crew', 'bouldering', 'Bouldering Crew', 'Gym sessions, beta swaps and chalky high-fives. All grades welcome, falling is part of it.', 124, 78, '#FF5C5C', false, array['climbing', 'bouldering', 'fitness'], array['running', 'cycling'], 16),
  ('home-bakers', 'cooking', 'Home Bakers', 'Sourdough starters, collapsed cakes and the occasional perfect croissant. Share the crumb shots.', 189, 112, '#FF914D', false, array['baking', 'cooking', 'bread'], array['cooking', 'gardening'], 17),
  ('urban-sketchers', 'drawing', 'Urban Sketchers', 'Drawing the city one street corner at a time. Pens, washes and on-location sketch walks.', 215, 143, '#FFD43B', false, array['drawing', 'sketching', 'urban'], array['drawing', 'photography'], 18)
