insert into public.posts (id, community_id, demo_author_id, author_name, type, title, body, interests, tags, reply_count, like_count, created_at) values
  ('p1', 'street-photography', 'u1', 'Maya Chen', 'discussion', 'I''ve been trying street photography for two weeks and I''m still scared to photograph strangers. How do you get over that?', 'Like I''ll see an amazing moment happening and I just freeze. By the time I convince myself to lift the camera, it''s gone. Does this ever go away?', array['photography'], array['beginner', 'advice'], 18, 18, '2026-08-04T14:22:00Z'),
  ('p2', 'acoustic-sessions', 'u2', 'Jake Morrison', 'question', 'Best songs to learn after you can finally play 4 chords?', 'I can do G, C, D, Em pretty smoothly now. What songs should I learn next that won''t make me cry?', array['guitar'], array['beginner', 'songs'], 24, 24, '2026-08-03T19:45:00Z'),
  ('p3', 'sketch-daily', 'u3', 'Priya Sharma', 'project', '30 days of drawing faces — my progress', 'Day 1 looked like a potato. Day 30 looks like a slightly more refined potato. But seriously, the improvement is real. Posting my favorites here.', array['drawing'], array['progress', 'faces', 'challenge'], 31, 31, '2026-08-05T10:30:00Z'),
  ('p4', 'student-chefs', 'u4', 'Sam Taylor', 'discussion', 'What''s the one kitchen tool that changed your cooking?', 'For me it was a decent chef''s knife. I was using this tiny dull paring knife for EVERYTHING. Game changer.', array['cooking'], array['tools', 'kitchen'], 42, 42, '2026-08-04T22:10:00Z'),
  ('p5', 'cinema-club', 'u5', 'Luna Park', 'idea', 'Weekly watch: films where nothing happens but everything happens', 'Think Lost in Translation, Paterson, Aftersun. Films that are technically plotless but emotionally devastating. Drop your picks.', array['film'], array['recommendations', 'slow-cinema'], 27, 27, '2026-08-02T16:55:00Z'),
  ('p6', 'couch-to-5k', 'u6', 'Alex Rivera', 'question', 'Is it normal to want to quit after week 3?', 'The jump from run 2 to run 3 intervals is brutal. My lungs feel like they''re filing a complaint. Please tell me this gets better.', array['running'], array['motivation', 'beginner'], 36, 36, '2026-08-05T07:15:00Z'),
  ('p7', 'beta-crushers', 'u7', 'Jordan Lee', 'project', 'Finally sent my first V5! Took me 3 months', 'That crimpy overhang route at my gym has been mocking me since May. Today I topped it clean. Hands are destroyed but my soul is whole.', array['bouldering'], array['send', 'milestone'], 15, 15, '2026-08-04T20:30:00Z'),
  ('p8', 'ml-study-group', 'u8', 'Nadia Hassan', 'discussion', 'Transformers paper reading group — who''s in?', 'Want to go through "Attention Is All You Need" line by line next week. Planning to meet virtually Tuesday 8pm. Anyone interested?', array['ai-ml'], array['study', 'papers', 'transformers'], 12, 12, '2026-08-03T13:00:00Z'),
  ('p9', 'creative-writing-circle', 'u9', 'Theo Williams', 'idea', 'Flash fiction challenge: write a complete story in exactly 55 words', 'Constraints breed creativity. Let''s try 55-word stories this week. Any genre, any topic. Post yours in the replies.', array['writing'], array['challenge', 'flash-fiction'], 19, 41, '2026-08-05T11:20:00Z'),
  ('p10', 'chess-beginners', 'u10', 'Kai Nakamura', 'discussion', 'I just discovered the London System and I feel like I''m cheating', 'Hear me out — same opening every game, solid structure, opponents don''t know what hit them below 800 elo. Is this what having a plan feels like?', array['chess'], array['openings', 'beginner'], 22, 47, '2026-08-04T15:45:00Z'),
  ('p11', 'plant-parents', 'u3', 'Priya Sharma', 'question', 'My monstera is giving me one new leaf per month. Is that normal or am I failing?', 'I water it, I give it light, I talk to it. But it''s growing so slowly. Meanwhile my roommate''s pothos is taking over the apartment.', array['gardening'], array['monstera', 'growth'], 14, 31, '2026-08-03T09:30:00Z'),
  ('p12', 'film-photography', 'u1', 'Maya Chen', 'project', 'First roll of Portra 400 — I think I''m in love', 'The colors are unreal. Shot a whole roll walking around campus on a Sunday morning. The warm tones are everything I dreamed of.', array['photography'], array['film', 'portra', 'first-roll'], 21, 45, '2026-08-02T18:20:00Z'),
  ('p13', 'indie-game-nights', 'u7', 'Jordan Lee', 'discussion', 'Outer Wilds is the best game ever made and I will not be taking questions', 'Just finished it. I''m emotionally wrecked. If you haven''t played it, go in completely blind. Trust me.', array['gaming'], array['outer-wilds', 'recommendation'], 33, 69, '2026-08-01T23:15:00Z'),
  ('p14', 'dance-freestyle', 'u5', 'Luna Park', 'question', 'How do you stop being self-conscious when dancing alone?', 'I want to freestyle but every time I try at home I feel ridiculous. My body just locks up. Anyone else deal with this?', array['dance'], array['beginner', 'confidence'], 16, 35, '2026-08-04T21:00:00Z')
